import { useEffect, useRef } from 'react'

import { loremRequest, type LoremRequest } from '#/lorem/index.ts'

/** How long the controls must rest before new text is made. */
export const autoGenerateDelay = 250

/**
 * Calls `onGenerate` once the controls have rested for {@link autoGenerateDelay}
 * and hold a valid request other than the one shown, like an autosave. A
 * value still being typed (`1` on the way to `12`) is never sent.
 */
export function useAutoGenerate(
  draft: { count: string; kind: string },
  shown: LoremRequest,
  onGenerate: (request: LoremRequest) => void,
): void {
  // The latest callback, so a new function each render does not restart the wait.
  const generate = useRef(onGenerate)
  generate.current = onGenerate

  useEffect(() => {
    const next = loremRequest.safeParse(draft)
    if (!next.success) return
    if (next.data.count === shown.count && next.data.kind === shown.kind) return
    const timer = setTimeout(
      () => generate.current(next.data),
      autoGenerateDelay,
    )
    return () => clearTimeout(timer)
  }, [draft.count, draft.kind, shown.count, shown.kind])
}
